// cl: /DNDEBUG /MD /EHsc
// RespawnUpdate method at 0x002A1A80 (121 B, ret then int3 padding).
// Identity: retail's ??_7RespawnUpdate@@6BRU_DeepBase@@@ holds its ILT
// 0x00030EB3 in slot 12, and it reads the module data (+4) and object (+8)
// as RespawnUpdate's primary view does; its meaning is unproven, so the name
// keeps the address. Like getSpawnTemplate (0x002A1B20) it caches a lookup:
// the image named at module data +0xAC, else the portrait image of the
// object's final template, kept at +0x24.

#include "../../../../../Libraries/Source/WWVegas/WWLib/ascii_string.h"

// Inline here, as in retail's caller: a null buffer or a zero length.
template <> inline bool StringBase<char>::isEmpty() const { return !m_data || !m_data->length; }

class Image;

class ImageCollection
{
public:
	const Image *findImageByName(const AsciiString &name);
};

extern ImageCollection *TheMappedImageCollection;

class Overridable
{
public:
	const Overridable *getFinalOverride() const;

	const Overridable *finalOverride() const
	{
		if (m_nextOverride)
			return m_nextOverride->getFinalOverride();
		return this;
	}

private:
	void *m_vptr;
	Overridable *m_nextOverride;
};

class ThingTemplatePortraitShim;

const Image *_bfme_getSelectedPortraitImage(const ThingTemplatePortraitShim *portraitTemplate,
	const ThingTemplatePortraitShim *objectTemplate);

class Object
{
public:
	const Overridable *getTemplate() const
	{
		return m_template ? m_template->finalOverride() : 0;
	}

private:
	void *m_vptr;
	Overridable *m_template;
};

struct RespawnUpdateModuleData
{
	unsigned char m_unmodelled_00[0xac];
	AsciiString m_imageName;
};

class RespawnUpdate
{
public:
	virtual const Image *rva002A1A80();

private:
	RespawnUpdateModuleData *m_moduleData;
	Object *m_object;
	unsigned char m_unmodelled_0C[0x24 - 0x0c];
	const Image *m_cachedImage;
};

// ?rva002A1A80@RespawnUpdate@@UAEPBVImage@@XZ
const Image *RespawnUpdate::rva002A1A80()
{
	if (m_cachedImage)
		return m_cachedImage;

	Object *obj = m_object;
	if (!m_moduleData->m_imageName.isEmpty())
	{
		m_cachedImage = TheMappedImageCollection->findImageByName(m_moduleData->m_imageName);
		if (m_cachedImage)
			return m_cachedImage;
		obj = m_object;
	}
	m_cachedImage = _bfme_getSelectedPortraitImage(
		(const ThingTemplatePortraitShim *)obj->getTemplate(),
		(const ThingTemplatePortraitShim *)obj);
	return m_cachedImage;
}
